{"task_id": "T24", "code": "import csv

def solve(line: str):
    """Parse a CSV line according to RFC 4180 basics.
    Returns a list of field strings. Empty line -> [''].
    """
    if line == "":
        return [""]
    # csv.reader returns an iterator of rows, each row is a list
    # Use default dialect which treats double quotes as escaping.
    # It also handles commas inside quoted fields.
    # We set strict=True to raise errors on malformed input.
    try:
        return next(csv.reader([line], strict=True))
    except Exception:
        # In case of malformed CSV, fallback to simple split handling similar to prior implementation
        fields = []
        cur = []
        i = 0
        n = len(line)
        in_quotes = False
        while i < n:
            c = line[i]
            if in_quotes:
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        cur.append('"')
                        i += 2
                        continue
                    else:
                        in_quotes = False
                        i += 1
                        continue
                else:
                    cur.append(c)
                    i += 1
                    continue
            else:
                if c == '"':
                    in_quotes = True
                    i += 1
                    continue
                elif c == ',':
                    fields.append(''.join(cur))
                    cur = []
                    i += 1
                    continue
                else:
                    cur.append(c)
                    i += 1
                    continue
        fields.append(''.join(cur))
        return fields
"}

