def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with O(n log n) time.
    """
    import bisect
    if not nums:
        return 0
    # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # find position to replace: leftmost >= x for strictly increasing, so use bisect_left
        pos = bisect.bisect_left(tails, x)
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
    return len(tails)

