    """Return the maximum number of non‑overlapping meetings.
    Each meeting is given as a two‑element iterable [start, end].
    A meeting may start exactly when another ends. Invalid meetings where
    end < start are ignored.
    """
    if not meetings:
        return 0
    # Filter out malformed meetings where end < start
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        if end < start:
            continue
        valid.append((start, end))
    if not valid:
        return 0
    # Greedy by earliest finishing time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -10**18
    for start, end in valid:
        if start >= current_end:
            count += 1
            current_end = end
    return count
