def solve(s):
    """Run-length encode a string.
    Returns a list of [character, count] pairs. Raises TypeError if input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result

