def solve(grid):
    """Count the number of islands in a binary grid.

    An island is a group of cells with value 1 connected horizontally or vertically.
    The grid may be empty or have rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(row) for row in grid ]

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            # explore neighbours
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))

    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

