    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in match:
            if not stack or stack[-1] != match[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

