    """Return the fewest number of coins needed to make *amount* using unlimited
    supply of the given *coins* (list of positive integers). Return -1 if impossible.
    """
    # Edge case: amount zero requires zero coins
    if amount == 0:
        return 0
    # Initialize DP array with a value larger than any possible answer
    # amount+1 is safe because the worst case is using all 1-value coins (if 1 in coins)
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    # Iterate over amounts and update using each coin
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If we can use coin c, see if using it improves the count
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != max_val else -1"}

